'use strict';
const previousStaffLogin=loginHTML;
loginHTML=function(){if(!emailLoginMode||loginType!=='employee'||/^\/admin\/?$/i.test(location.pathname))return previousStaffLogin();return `<main class="auth-layout"><section><div class="brand"></div><div class="eyebrow">رجعة · فريق النشاط</div><h1>دخول الموظف</h1><p>اسم المستخدم وكلمة المرور يعطيك إياها صاحب النشاط.</p><div class="notice mt">أضف الزيارات واستبدل المكافآت من شاشة واحدة.</div></section><section class="panel auth-panel"><h2>دخول الموظف</h2><div class="segmented"><button type="button" data-action="email-role" data-kind="owner">صاحب النشاط</button><button type="button" class="active" data-action="email-role" data-kind="employee">الموظف</button></div><form id="staff-login"><label class="field"><span>اسم المستخدم</span><input class="input" name="username" autocomplete="username" dir="ltr" minlength="3" maxlength="32" required></label><label class="field"><span>كلمة المرور · 6 أرقام</span><input class="input" name="password" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" autocomplete="current-password" required></label><p class="error" id="staff-error"></p><button type="submit" class="btn primary full">تسجيل الدخول</button></form><p class="sub mt">نسيت الرمز؟ اطلب من صاحب النشاط إعادة تعيينه.</p></section></main>`;};
const previousStaffModal=modal;
modal=function(title,html,footer){if(emailLoginMode&&html.includes('id="employee-form"'))html=`<form id="employee-form"><label class="field"><span>اسم الموظف</span><input class="input" name="name" maxlength="40" required></label><label class="field"><span>رقم الجوال</span><input class="input" name="phone" type="tel" autocomplete="tel" dir="ltr" placeholder="05xxxxxxxx" required></label><label class="field"><span>اسم المستخدم</span><input class="input" name="username" autocomplete="off" dir="ltr" pattern="[A-Za-z0-9._-]{3,32}" minlength="3" maxlength="32" placeholder="ahmed.01" required></label><label class="field"><span>كلمة المرور · 6 أرقام</span><input class="input" name="password" type="password" inputmode="numeric" autocomplete="new-password" pattern="[0-9]{6}" minlength="6" maxlength="6" required></label>${staffCardChoices()}<p class="sub">أعطِ الموظف اسم المستخدم والرمز ليدخل مباشرة. الاسم فريد في رجعة.</p><p class="error" id="employee-error"></p><button type="submit" class="btn primary full">إضافة الموظف</button></form>`;return previousStaffModal(title,html,footer);};
const previousStaffList=employeesHTML;
employeesHTML=function(){const html=previousStaffList();return html.replace(/<td><button class="btn quiet small" data-action="toggle-employee" data-id="([^"]+)"/g,'<td><button class="btn quiet small" data-action="reset-staff" data-id="$1">تغيير الرمز</button><button class="btn quiet small" data-action="staff-cards" data-id="$1">البطاقات المسموحة</button><button class="btn quiet small" data-action="toggle-employee" data-id="$1"').replace('تسجيل الدخول هنا تمثيلي للمراجعة؛ الحماية الفعلية تضاف عند التشغيل.','يدخل الموظف باسم المستخدم ورمزه، ويمكنك إيقاف وصوله أو تغيير الرمز.');};
window.addEventListener('click',e=>{const b=e.target.closest('[data-action=reset-staff]');if(!emailLoginMode||!b)return;e.preventDefault();e.stopImmediatePropagation();modal('تغيير رمز الموظف',`<form id="staff-reset"><input type="hidden" name="id" value="${esc(b.dataset.id)}"><label class="field"><span>الرمز الجديد · 6 أرقام</span><input class="input" name="password" type="password" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required></label><p class="sub">يسجل الموظف الدخول مجددًا بالرمز الجديد.</p><p class="error" id="staff-error"></p><button class="btn primary full" type="submit">حفظ الرمز</button></form>`);},true);
window.addEventListener('submit',async e=>{const f=e.target;if(!emailLoginMode||!['staff-login','staff-reset'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();const d=new FormData(f),button=f.querySelector('button');if(button.disabled)return;button.disabled=true;try{if(f.id==='staff-login')emailAccept(await api('/api/staff/login',{username:d.get('username'),password:d.get('password')}));else{await serverCommand({action:'reset-employee',id:d.get('id'),password:d.get('password')});document.querySelector('#modal').close();toast('تم تغيير رمز الموظف.');}}catch(err){document.querySelector('#staff-error').textContent=err.message;}finally{button.disabled=false;}},true);
const previousStaffRender=render;
render=function(){previousStaffRender();if(emailLoginMode&&document.querySelector('#staff-login'))document.querySelector('.auth-layout>section>p').textContent='اسم المستخدم وكلمة المرور يعطيك إياها صاحب النشاط.';if(!emailLoginMode||view!=='employees'||!shop())return;document.querySelectorAll('[data-action=toggle-employee]').forEach(b=>{const e=shop().employees.find(x=>x.id===b.dataset.id);if(e?.username){const cell=b.closest('tr')?.querySelector('td');if(cell&&!cell.querySelector('.staff-username'))cell.insertAdjacentHTML('beforeend',`<small class="sub staff-username" dir="ltr">${esc(e.username)}</small>`);}});};
render();

function staffCardChoices(employee){const cards=db.shops.filter(s=>!s.archivedAt);return `<fieldset class="staff-card-choices"><legend>البطاقات التي يديرها الموظف</legend><p class="sub">حدد بطاقة أو أكثر. تظهر له هذه البطاقات فقط عند الدخول.</p>${cards.map(c=>`<label class="terms"><input type="checkbox" name="programs" value="${esc(c.id)}" ${employee?(!Array.isArray(employee.programs)||employee.programs.includes(c.id)?'checked':''):c.id===db.shop?'checked':''}>${esc(c.card.title||c.name)}</label>`).join('')}</fieldset>`;}
window.addEventListener('click',e=>{const b=e.target.closest('[data-action=staff-cards]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(!canOperate()){toast('يلزم تفعيل الاشتراك.');return;}const employee=shop().employees.find(x=>x.id===b.dataset.id);modal('بطاقات الموظف',`<form id="staff-cards-form"><input type="hidden" name="id" value="${esc(employee.id)}"><h3>${esc(employee.name)}</h3>${staffCardChoices(employee)}<p class="error" id="staff-cards-error"></p><button type="submit" class="btn primary full">حفظ البطاقات</button></form>`);},true);
window.addEventListener('submit',async e=>{if(e.target.id!=='staff-cards-form')return;e.preventDefault();e.stopImmediatePropagation();const f=e.target,d=new FormData(f),b=f.querySelector('button');b.disabled=true;try{const programs=d.getAll('programs');if(!programs.length)throw Error('حدد بطاقة واحدة على الأقل.');await serverCommand({action:'assign-employee',id:d.get('id'),programs});document.querySelector('#modal').close();toast('تم تحديث بطاقات الموظف.');}catch(err){f.querySelector('.error').textContent=err.message;}finally{b.disabled=false;}},true);
let staffSessionCheck=false;
async function refreshStaffSession(){if(!serverMode||principal?.kind!=='employee'||staffSessionCheck)return;staffSessionCheck=true;try{const previousView=view,previousPage=publicPage,previousShop=db.shop;const j=await api('/api/state');acceptServer(j);if(db.shops.some(s=>s.id===previousShop))db.shop=previousShop;view=previousView;publicPage=previousPage;render();}catch(err){if([401,403].includes(err.status)){stopCamera();principal=null;publicPage='login';loginType='employee';render();toast('انتهت جلسة الموظف أو تغيّرت صلاحياته. سجّل الدخول مجددًا.');}}finally{staffSessionCheck=false;}}
setInterval(()=>{if(!document.hidden)refreshStaffSession();},15000);
window.addEventListener('focus',refreshStaffSession);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshStaffSession();});
